#!/usr/bin/env node
/* =========================================================
   FORGE ENGINE — Fase 1
   Sin dependencias: solo Node (>=18). Funciona en Termux.
   - Sirve forge.html en http://127.0.0.1:PUERTO
   - Inyecta un token de sesión en la página (no hay que copiar nada)
   - GET /api/health confirma que el Engine responde
   Solo escucha en 127.0.0.1: nadie más en tu red puede usarlo.
   ========================================================= */
'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const os = require('os');
const { spawn } = require('child_process');

const VERSION = '0.4.0';
const PORT = parseInt(process.env.FORGE_PORT, 10) || 8787;
const HOST = '127.0.0.1';
// Los datos viven en la carpeta personal (en Termux: ~/forge-data), no junto al archivo,
// porque el almacenamiento compartido de Android no soporta npm ni git.
const HOME = process.env.FORGE_HOME || path.join(os.homedir(), 'forge-data');
const PROJECTS_DIR = path.join(HOME, 'projects');
const PLUGINS_DIR = path.join(HOME, 'plugins');
const CHATS_DIR = path.join(HOME, 'chats');

// La interfaz va incluida en este mismo archivo (la inserta build.js).
// Si corrés el código fuente sin compilar, lee forge.html de al lado.
const HTML_B64 = '';
const EMBEDDED_HTML = HTML_B64.startsWith('__') ? null : Buffer.from(HTML_B64, 'base64').toString('utf8');
const HTML_FILE = path.join(__dirname, 'forge.html');

// Token nuevo en cada arranque. Se inyecta en el HTML que sirve este mismo servidor.
const TOKEN = crypto.randomBytes(16).toString('hex');
const STARTED = Date.now();

for (const dir of [PROJECTS_DIR, PLUGINS_DIR, CHATS_DIR]) fs.mkdirSync(dir, { recursive: true });

function sendJson(res, status, body) {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Content-Length': Buffer.byteLength(data),
  });
  res.end(data);
}

// Evita que otra página abierta en el navegador le hable al Engine (DNS rebinding).
function hostAllowed(req) {
  const h = String(req.headers.host || '').toLowerCase();
  return h === `${HOST}:${PORT}` || h === `localhost:${PORT}`;
}

function tokenOk(req) {
  const given = String(req.headers['x-forge-token'] || '');
  const a = Buffer.from(given);
  const b = Buffer.from(TOKEN);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function serveHtml(res) {
  const load = (cb) => (EMBEDDED_HTML !== null ? cb(null, EMBEDDED_HTML) : fs.readFile(HTML_FILE, 'utf8', cb));
  load((err, html) => {
    if (err) {
      res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('No encuentro la interfaz de Forge (forge.html).\nBuscado en: ' + HTML_FILE);
    }
    const inject = `<script>window.FORGE_ENGINE=${JSON.stringify({ token: TOKEN, version: VERSION })};</script>`;
    const out = html.includes('<head>') ? html.replace('<head>', '<head>' + inject) : inject + html;
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store',
    });
    res.end(out);
  });
}

/* =========================================================
   PROYECTOS Y RUTAS SEGURAS
   Cada chat de Forge = una carpeta real en <datos>/projects/<id>.
   ========================================================= */
function slugProject(name) {
  const s = String(name == null ? '' : name).toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^[.-]+/, '').slice(0, 60);
  return s || 'default';
}
function projectDir(project) {
  const dir = path.join(PROJECTS_DIR, slugProject(project));
  fs.mkdirSync(dir, { recursive: true });
  return fs.realpathSync(dir);
}
// Resuelve una ruta relativa dentro del proyecto. Rechaza "..", rutas absolutas y enlaces simbólicos que escapen.
function resolveInside(base, rel) {
  rel = String(rel == null ? '.' : rel).replace(/\\/g, '/');
  if (rel.includes('\0')) throw new Error('Ruta inválida.');
  if (path.isAbsolute(rel)) throw new Error('Usá rutas relativas al proyecto (sin "/" al principio).');
  const target = path.resolve(base, rel);
  if (target !== base && !target.startsWith(base + path.sep)) throw new Error('Ruta fuera del proyecto: no permitido.');
  let probe = target;
  for (;;) {
    try { fs.lstatSync(probe); break; } catch (_) {
      const up = path.dirname(probe);
      if (up === probe) break;
      probe = up;
    }
  }
  let real;
  try { real = fs.realpathSync(probe); } catch (_) { throw new Error('Enlace simbólico roto: no permitido.'); }
  if (real !== base && !real.startsWith(base + path.sep)) throw new Error('Ruta fuera del proyecto (enlace simbólico): no permitido.');
  return target;
}
// .git solo se modifica con la herramienta git (un hook escrito a mano ejecutaría código al hacer commit).
function resolveWritable(base, rel) {
  const target = resolveInside(base, rel);
  const segs = path.relative(base, target).split(path.sep);
  if (segs.includes('.git')) throw new Error('La carpeta .git solo se toca con la herramienta git.');
  return target;
}
function need(input, key) {
  const v = input[key];
  if (typeof v !== 'string' || !v.trim()) throw new Error('Falta el parámetro "' + key + '" (texto).');
  return v;
}
function cleanMsg(e, base) {
  return String((e && e.message) || e).split(base).join('.');
}

/* =========================================================
   REGISTRO DE HERRAMIENTAS (Tool Registry)
   Cada herramienta declara: nombre, descripción, esquema,
   permiso ('auto' | 'confirm' | función que decide por llamada)
   y run(). Los plugins de la Fase 5 usarán este mismo registro.
   ========================================================= */
const TOOLS = new Map();
function registerTool(def) { TOOLS.set(def.name, def); }

const SKIP_DIRS = new Set(['node_modules', '.git']);
const MAX_READ = 200 * 1024;
const MAX_WRITE = 5 * 1024 * 1024;

registerTool({
  name: 'fs_list',
  label: 'Listando {path}',
  description: 'Lista archivos y carpetas REALES del proyecto en el dispositivo. "path" es relativo al proyecto (por defecto la raíz). Con recursive=true baja hasta 6 niveles (omite node_modules y .git).',
  input_schema: { type: 'object', properties: { path: { type: 'string', description: 'Carpeta a listar, ej: src. Por defecto ".".' }, recursive: { type: 'boolean' } }, required: [] },
  permission: 'auto',
  run(input, { base }) {
    const dir = resolveInside(base, input.path || '.');
    if (!fs.statSync(dir).isDirectory()) throw new Error('No es una carpeta.');
    const out = [];
    (function walk(d, prefix, depth) {
      const entries = fs.readdirSync(d, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name));
      for (const e of entries) {
        if (out.length >= 300) return;
        if (e.isDirectory()) {
          if (SKIP_DIRS.has(e.name)) { out.push(prefix + e.name + '/  (omitida)'); continue; }
          out.push(prefix + e.name + '/');
          if (input.recursive && depth < 6) walk(path.join(d, e.name), prefix + e.name + '/', depth + 1);
        } else {
          let size = 0;
          try { size = fs.statSync(path.join(d, e.name)).size; } catch (_) { /* enlace roto */ }
          out.push(prefix + e.name + '  (' + size + ' bytes)');
        }
      }
    })(dir, '', 0);
    if (!out.length) return '(carpeta vacía)';
    return out.join('\n') + (out.length >= 300 ? '\n[...lista recortada a 300 entradas]' : '');
  },
});

registerTool({
  name: 'fs_read',
  label: 'Leyendo {path}',
  description: 'Lee un archivo de texto REAL del proyecto (hasta 200 KB; si es más grande devuelve el principio).',
  input_schema: { type: 'object', properties: { path: { type: 'string', description: 'Ruta relativa, ej: src/main.js' } }, required: ['path'] },
  permission: 'auto',
  run(input, { base }) {
    const file = resolveInside(base, need(input, 'path'));
    const st = fs.statSync(file);
    if (st.isDirectory()) throw new Error('Es una carpeta; usá fs_list.');
    const buf = fs.readFileSync(file);
    if (buf.subarray(0, 8000).includes(0)) return 'Archivo binario (' + st.size + ' bytes): no se puede leer como texto.';
    const text = buf.subarray(0, MAX_READ).toString('utf8');
    return buf.length > MAX_READ ? text + '\n[...recortado: el archivo tiene ' + buf.length + ' bytes]' : text;
  },
});

registerTool({
  name: 'fs_write',
  label: 'Escribiendo {path}',
  description: 'Crea o sobreescribe un archivo REAL del proyecto con contenido completo (crea las carpetas intermedias). No se puede escribir dentro de .git.',
  input_schema: { type: 'object', properties: { path: { type: 'string', description: 'Ruta relativa, ej: src/enemigo.js' }, content: { type: 'string', description: 'Contenido completo y final del archivo.' } }, required: ['path', 'content'] },
  permission: 'auto',
  async run(input, { base }) {
    const file = resolveWritable(base, need(input, 'path'));
    const content = String(input.content == null ? '' : input.content);
    if (Buffer.byteLength(content) > MAX_WRITE) throw new Error('Contenido demasiado grande (máximo 5 MB).');
    if (file === base) throw new Error('Indicá un nombre de archivo.');
    if (fs.existsSync(file) && fs.statSync(file).isDirectory()) throw new Error('Esa ruta es una carpeta.');
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
    return 'Archivo "' + path.relative(base, file) + '" guardado (' + content.length + ' caracteres).' + (await syntaxNote(base, file));
  },
});

registerTool({
  name: 'fs_mkdir',
  label: 'Creando carpeta {path}',
  description: 'Crea una carpeta (y las intermedias) dentro del proyecto.',
  input_schema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] },
  permission: 'auto',
  run(input, { base }) {
    const dir = resolveWritable(base, need(input, 'path'));
    fs.mkdirSync(dir, { recursive: true });
    return 'Carpeta "' + path.relative(base, dir) + '" lista.';
  },
});

registerTool({
  name: 'fs_move',
  label: 'Moviendo {from} → {to}',
  description: 'Mueve o renombra un archivo o carpeta del proyecto. Falla si el destino ya existe.',
  input_schema: { type: 'object', properties: { from: { type: 'string' }, to: { type: 'string' } }, required: ['from', 'to'] },
  permission: 'auto',
  run(input, { base }) {
    const a = resolveWritable(base, need(input, 'from'));
    const b = resolveWritable(base, need(input, 'to'));
    if (a === base || b === base) throw new Error('No se puede mover la raíz del proyecto.');
    if (!fs.existsSync(a)) throw new Error('No existe "' + input.from + '".');
    if (fs.existsSync(b)) throw new Error('El destino ya existe: "' + input.to + '".');
    fs.mkdirSync(path.dirname(b), { recursive: true });
    fs.renameSync(a, b);
    return 'Movido: ' + input.from + ' → ' + input.to;
  },
});

registerTool({
  name: 'fs_copy',
  label: 'Copiando {from} → {to}',
  description: 'Copia un archivo o carpeta dentro del proyecto. Falla si el destino ya existe.',
  input_schema: { type: 'object', properties: { from: { type: 'string' }, to: { type: 'string' } }, required: ['from', 'to'] },
  permission: 'auto',
  run(input, { base }) {
    const a = resolveInside(base, need(input, 'from'));
    const b = resolveWritable(base, need(input, 'to'));
    if (!fs.existsSync(a)) throw new Error('No existe "' + input.from + '".');
    if (fs.existsSync(b)) throw new Error('El destino ya existe: "' + input.to + '".');
    if (b === base || (fs.statSync(a).isDirectory() && (b + path.sep).startsWith(a + path.sep))) throw new Error('Destino inválido.');
    fs.mkdirSync(path.dirname(b), { recursive: true });
    fs.cpSync(a, b, { recursive: true, errorOnExist: true, force: false });
    return 'Copiado: ' + input.from + ' → ' + input.to;
  },
});

registerTool({
  name: 'fs_delete',
  label: 'Eliminando {path}',
  description: 'Elimina un archivo o carpeta del proyecto. Pide confirmación a la persona. No se puede borrar la raíz del proyecto.',
  input_schema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] },
  permission: () => ({ level: 'confirm', reason: 'Borra archivos de forma permanente.' }),
  summary: (i) => 'Eliminar del proyecto: ' + i.path,
  run(input, { base }) {
    const t = resolveWritable(base, need(input, 'path'));
    if (t === base) throw new Error('No se puede borrar la raíz del proyecto.');
    if (!fs.existsSync(t) && !isLink(t)) throw new Error('No existe "' + input.path + '".');
    fs.rmSync(t, { recursive: true, force: false });
    return 'Eliminado: ' + input.path;
  },
});
function isLink(p) { try { return fs.lstatSync(p).isSymbolicLink(); } catch (_) { return false; } }

/* ---------- Procesos (terminal y git) ---------- */
function runProcess(cmd, argv, { cwd, timeoutMs, env }) {
  return new Promise((resolve) => {
    let out = '';
    let timedOut = false;
    let settled = false;
    const child = spawn(cmd, argv, {
      cwd, env, stdio: ['ignore', 'pipe', 'pipe'], detached: process.platform !== 'win32',
    });
    const add = (d) => { out += d.toString('utf8'); if (out.length > 400000) out = out.slice(-200000); };
    child.stdout.on('data', add);
    child.stderr.on('data', add);
    const killTree = () => {
      try { process.kill(-child.pid, 'SIGKILL'); } catch (_) { try { child.kill('SIGKILL'); } catch (__) { /* ya terminó */ } }
    };
    const timer = setTimeout(() => { timedOut = true; killTree(); }, timeoutMs);
    const done = (r) => { if (settled) return; settled = true; clearTimeout(timer); resolve(Object.assign({ out, timedOut }, r)); };
    child.on('error', (err) => done({ code: null, spawnError: err }));
    child.on('close', (code, signal) => done({ code, signal }));
  });
}
function tail(s, max) {
  return s.length <= max ? s : '[...salida recortada, mostrando el final]\n' + s.slice(-max);
}
function baseEnv() {
  return Object.assign({}, process.env, { CI: '1', NO_COLOR: '1', FORCE_COLOR: '0', GIT_TERMINAL_PROMPT: '0', GIT_EDITOR: 'true' });
}

/* ---------- Clasificación de comandos ----------
   OJO: es un filtro de sensatez, no una cárcel. Un programa que la IA
   escriba y ejecute con node puede hacer lo que tu usuario de Termux
   pueda hacer. Lo que te protege de verdad es el aislamiento de Termux
   dentro de Android y que todo lo dudoso te pida confirmación. */
const AUTO_CMDS = new Set(['node', 'python', 'python3', 'ls', 'cat', 'head', 'tail', 'wc', 'grep', 'find', 'pwd', 'echo', 'mkdir', 'touch', 'cp', 'mv', 'sort', 'uniq', 'diff', 'tree']);
const NPM_AUTO = new Set(['test', 't', 'run', 'run-script', 'start', 'ls', 'list', '-v', '--version']);
const BLOCKED_CMD = [
  [/(^|[\s;&|(])(sudo|su|doas)(\s|$)/, 'sudo/su no están permitidos.'],
  [/\b(mkfs|fdisk|dd|shutdown|reboot|poweroff|halt|passwd|mount|umount)\b/, 'Comando de sistema no permitido.'],
  [/:\(\)\s*\{/, 'Patrón peligroso (fork bomb).'],
  [/\|\s*(sh|bash|zsh|dash)\b/, 'No se permite pasar descargas directo a un intérprete de shell.'],
  [/(^|[\s"'=])~/, 'Referencia a "~" (fuera del proyecto).'],
  [/\$\{?HOME\}?/, 'Referencia a $HOME (fuera del proyecto).'],
  [/(^|[\s"'=/])\.\.($|[\s"'/])/, 'Referencia a ".." (fuera del proyecto).'],
  [/(^|[\s"'=(])\/(?!dev\/null\b|tmp\b)[^\s"']*/, 'Ruta absoluta fuera del proyecto (usá rutas relativas).'],
];
function classifyCommand(cmd) {
  const c = String(cmd == null ? '' : cmd).trim();
  if (!c) return { level: 'blocked', reason: 'Comando vacío.' };
  if (c.length > 2000) return { level: 'blocked', reason: 'Comando demasiado largo.' };
  for (const [re, reason] of BLOCKED_CMD) if (re.test(c)) return { level: 'blocked', reason };
  if (/[;&|<>`$(){}\\\n]/.test(c)) return { level: 'confirm', reason: 'El comando encadena, redirige o usa sustitución (; & | > $ ...).' };
  const parts = c.split(/\s+/);
  const first = parts[0];
  if (first === 'npm') {
    return NPM_AUTO.has(parts[1]) ? { level: 'auto' } : { level: 'confirm', reason: 'npm puede instalar o cambiar dependencias.' };
  }
  if (AUTO_CMDS.has(first)) {
    if (first === 'find' && /-(exec|execdir|delete|ok)\b/.test(c)) return { level: 'confirm', reason: 'find con acciones.' };
    return { level: 'auto' };
  }
  return { level: 'confirm', reason: 'Comando fuera de la lista segura.' };
}

registerTool({
  name: 'run_command',
  label: 'Ejecutando: {command}',
  description: 'Ejecuta un comando de terminal REAL (sh) dentro de la carpeta del proyecto y devuelve la salida y el código de salida. Corren solos: node, python, npm test/run/start, ls, cat, grep, mkdir, cp, mv y similares. Instalar dependencias (npm install), encadenar con && o |, y cualquier otro comando piden confirmación a la persona. Sin sudo ni rutas fuera del proyecto. Termina solo tras el timeout (60 s por defecto, máximo 300), así que no lances servidores que no terminan salvo que sea a propósito.',
  input_schema: { type: 'object', properties: { command: { type: 'string', description: 'Ej: node juego.js, npm test, npm run build' }, timeout_seconds: { type: 'number', description: 'Por defecto 60, máximo 300.' } }, required: ['command'] },
  permission: (i) => classifyCommand(i.command),
  summary: (i) => 'Ejecutar en el proyecto:\n' + i.command,
  async run(input, { base }) {
    const command = need(input, 'command');
    const secs = Math.min(Math.max(Number(input.timeout_seconds) || 60, 1), 300);
    const r = await runProcess('sh', ['-c', command], { cwd: base, timeoutMs: secs * 1000, env: baseEnv() });
    let text = '$ ' + command + '\n' + tail(r.out.trim(), 8000);
    if (r.spawnError) return { ok: false, text: '$ ' + command + '\nNo se pudo iniciar: ' + r.spawnError.message };
    if (r.timedOut) return { ok: false, text: text + '\n[Detenido: superó el límite de ' + secs + ' s]' };
    text += '\n[código de salida ' + (r.code === null ? 'señal ' + r.signal : r.code) + ']';
    return { ok: r.code === 0, text };
  },
});

/* ---------- Git ---------- */
const GIT_AUTO = new Set(['status', 'diff', 'log', 'show', 'add', 'commit', 'init', 'stash', 'rev-parse', 'ls-files', 'blame', 'tag', 'branch', 'checkout', 'switch']);
function classifyGit(args) {
  if (!Array.isArray(args) || !args.length || args.length > 40 || args.some((a) => typeof a !== 'string' || a.includes('\0'))) {
    return { level: 'blocked', reason: '"args" debe ser una lista de textos, ej: ["status"].' };
  }
  if (args.some((a) => /^--(upload-pack|receive-pack|exec)\b/.test(a))) return { level: 'blocked', reason: 'Opción de git no permitida.' };
  const sub = args[0];
  if (sub.startsWith('-')) return { level: 'confirm', reason: 'Opciones globales de git (-c, -C, ...).' };
  if (!GIT_AUTO.has(sub)) return { level: 'confirm', reason: 'git ' + sub + ' puede tocar remotos o descartar cambios.' };
  if (['checkout', 'switch'].includes(sub) && args.some((a) => a === '--' || /^(-f|--force|-B|--discard-changes)$/.test(a))) return { level: 'confirm', reason: 'Puede descartar cambios sin guardar.' };
  if (sub === 'branch' && args.some((a) => /^-(D|d|m|M|f|-force|-delete)$/.test(a))) return { level: 'confirm', reason: 'Borra o renombra ramas.' };
  if (sub === 'stash' && ['drop', 'clear', 'pop'].includes(args[1])) return { level: 'confirm', reason: 'Descarta o reaplica cambios guardados.' };
  if (sub === 'tag' && args.some((a) => /^-(d|-delete|f|-force)$/.test(a))) return { level: 'confirm', reason: 'Borra etiquetas.' };
  return { level: 'auto' };
}
let gitIdentityEnv = null;
function gitEnv() {
  if (gitIdentityEnv === null) {
    gitIdentityEnv = {};
    try {
      const r = require('child_process').spawnSync('git', ['config', 'user.name'], { encoding: 'utf8' });
      if (!r.error && !String(r.stdout).trim()) {
        gitIdentityEnv = { GIT_AUTHOR_NAME: 'Forge', GIT_AUTHOR_EMAIL: 'forge@localhost', GIT_COMMITTER_NAME: 'Forge', GIT_COMMITTER_EMAIL: 'forge@localhost' };
      }
    } catch (_) { /* sin git */ }
  }
  return Object.assign(baseEnv(), gitIdentityEnv);
}
registerTool({
  name: 'git',
  label: 'git {args}',
  description: 'Ejecuta git dentro del proyecto. "args" es una lista, ej: ["init"], ["add","."], ["commit","-m","mensaje"], ["status"], ["diff"], ["log","--oneline","-10"]. status/diff/log/add/commit/init/branch/checkout corren solos; push, pull, fetch, clone, remote, reset, clean, rebase, merge y config piden confirmación.',
  input_schema: { type: 'object', properties: { args: { type: 'array', items: { type: 'string' }, description: 'Argumentos de git, uno por elemento.' } }, required: ['args'] },
  permission: (i) => classifyGit(i.args),
  summary: (i) => 'Ejecutar: git ' + (Array.isArray(i.args) ? i.args.join(' ') : ''),
  async run(input, { base }) {
    const args = input.args;
    const r = await runProcess('git', args, { cwd: base, timeoutMs: 120000, env: gitEnv() });
    if (r.spawnError) {
      return { ok: false, text: r.spawnError.code === 'ENOENT' ? 'git no está instalado. En Termux: pkg install git' : 'No se pudo iniciar git: ' + r.spawnError.message };
    }
    let text = '$ git ' + args.join(' ') + '\n' + tail(r.out.trim(), 12000);
    if (r.timedOut) return { ok: false, text: text + '\n[Detenido: superó los 120 s]' };
    text += '\n[código de salida ' + (r.code === null ? 'señal ' + r.signal : r.code) + ']';
    return { ok: r.code === 0, text };
  },
});

/* =========================================================
   AUTOCORRECCIÓN: revisión de sintaxis sin gastar rondas de IA
   fs_write revisa el archivo recién guardado y devuelve el error
   en la misma respuesta; verify_project revisa todo el proyecto.
   ========================================================= */
const TMP_DIR = path.join(HOME, '.tmp');
const MEMORY_DIR = path.join(HOME, 'memory');
for (const dir of [TMP_DIR, MEMORY_DIR]) fs.mkdirSync(dir, { recursive: true });

const ESM_HINT = /Cannot use import statement|Unexpected token 'export'|Unexpected token 'import'|Unexpected reserved word|await is only valid|import\.meta/;
async function nodeCheck(file) {
  const r = await runProcess(process.execPath, ['--check', file], { cwd: HOME, timeoutMs: 15000, env: baseEnv() });
  if (r.spawnError) return { ok: true }; // no se pudo revisar: no inventamos errores
  if (r.code === 0) return { ok: true };
  const lines = r.out.split('\n');
  const lm = /:(\d+)\s*$/.exec(lines[0] || '');
  const mm = /^(\w*Error:.*)$/m.exec(r.out);
  return {
    ok: false,
    line: lm ? Number(lm[1]) : 0,
    src: (lines[1] || '').trim().slice(0, 120),
    msg: mm ? mm[1].slice(0, 200) : r.out.trim().slice(0, 200),
    raw: r.out,
  };
}
async function checkJs(file) {
  let r = await nodeCheck(file);
  if (!r.ok && ESM_HINT.test(r.raw || r.msg)) {
    // Puede ser un módulo de navegador (import/export): reintenta como .mjs antes de dar error.
    const tmp = path.join(TMP_DIR, 'esm-' + crypto.randomBytes(4).toString('hex') + '.mjs');
    try {
      fs.copyFileSync(file, tmp);
      const r2 = await nodeCheck(tmp);
      if (r2.ok) return { ok: true };
      r = r2;
    } finally { fs.rmSync(tmp, { force: true }); }
  }
  return r;
}
function fmtJs(r) { return (r.line ? 'línea ' + r.line + ': ' : '') + r.msg + (r.src ? '\n    → ' + r.src : ''); }

// Devuelve un texto de error o null si está bien / el tipo no se revisa.
async function checkFile(base, abs) {
  const rel = path.relative(base, abs).split(path.sep).join('/');
  const ext = path.extname(abs).toLowerCase();
  if (['.js', '.cjs', '.mjs'].includes(ext)) {
    const r = await checkJs(abs);
    return r.ok ? null : rel + ' → ' + fmtJs(r);
  }
  if (ext === '.json') {
    try { JSON.parse(fs.readFileSync(abs, 'utf8')); return null; } catch (e) { return rel + ' → JSON inválido: ' + e.message; }
  }
  if (ext === '.html' || ext === '.htm') {
    const html = fs.readFileSync(abs, 'utf8');
    const re = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
    let m; let n = 0;
    while ((m = re.exec(html))) {
      const attrs = m[1];
      if (/\bsrc\s*=/i.test(attrs)) continue;
      const t = /type\s*=\s*["']?([^"'\s>]+)/i.exec(attrs);
      const type = t ? t[1].toLowerCase() : '';
      if (type && !['text/javascript', 'application/javascript', 'module'].includes(type)) continue;
      n++;
      if (!m[2].trim()) continue;
      const startLine = html.slice(0, m.index + m[0].indexOf('>') + 1).split('\n').length;
      const tmp = path.join(TMP_DIR, 'chk-' + crypto.randomBytes(4).toString('hex') + (type === 'module' ? '.mjs' : '.js'));
      fs.writeFileSync(tmp, m[2]);
      try {
        const r = await checkJs(tmp);
        if (!r.ok) return rel + ' (script ' + n + ') → ' + (r.line ? 'línea ' + (startLine + r.line - 1) + ': ' : '') + r.msg + (r.src ? '\n    → ' + r.src : '');
      } finally { fs.rmSync(tmp, { force: true }); }
    }
  }
  return null;
}
const CHECKABLE = new Set(['.js', '.cjs', '.mjs', '.json', '.html', '.htm']);
async function syntaxNote(base, abs) {
  if (!CHECKABLE.has(path.extname(abs).toLowerCase())) return '';
  try {
    const err = await checkFile(base, abs);
    return err ? '\n⚠ ERROR DE SINTAXIS — corregilo ahora: ' + err : '\nSintaxis OK.';
  } catch (_) { return ''; }
}

registerTool({
  name: 'verify_project',
  label: 'Verificando el proyecto',
  description: 'Revisa la sintaxis de todos los .js/.mjs/.json/.html del proyecto (incluye los <script> de los HTML) y corre "npm test" si el proyecto define un test real. Usala después de un cambio grande, antes de dar la tarea por terminada.',
  input_schema: { type: 'object', properties: {}, required: [] },
  permission: 'auto',
  async run(input, { base }) {
    const files = [];
    (function walk(d) {
      for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        if (files.length >= 300) return;
        const p = path.join(d, e.name);
        if (e.isDirectory()) { if (!SKIP_DIRS.has(e.name)) walk(p); } else if (e.isFile() && CHECKABLE.has(path.extname(e.name).toLowerCase())) files.push(p);
      }
    })(base);
    const problems = [];
    for (const f of files) {
      const err = await checkFile(base, f);
      if (err) problems.push('- ' + err);
    }
    let text = problems.length
      ? 'Revisados ' + files.length + ' archivo(s). Problemas de sintaxis:\n' + problems.join('\n')
      : 'Sintaxis OK en ' + files.length + ' archivo(s) (.js/.json/.html).';
    let ok = problems.length === 0;
    const pj = path.join(base, 'package.json');
    if (fs.existsSync(pj)) {
      let test = '';
      try { test = (JSON.parse(fs.readFileSync(pj, 'utf8')).scripts || {}).test || ''; } catch (_) { text += '\nOJO: package.json no es un JSON válido.'; ok = false; }
      if (test && !/no test specified/i.test(test)) {
        const r = await runProcess('npm', ['test'], { cwd: base, timeoutMs: 90000, env: baseEnv() });
        if (r.spawnError) text += '\nnpm test: no se pudo iniciar (' + r.spawnError.message + ').';
        else if (r.timedOut) { text += '\nnpm test: superó los 90 s.'; ok = false; }
        else { text += '\nnpm test → ' + (r.code === 0 ? 'OK' : 'FALLÓ (código ' + r.code + ')') + '\n' + tail(r.out.trim(), 4000); if (r.code !== 0) ok = false; }
      }
    }
    return { ok, text };
  },
});

/* =========================================================
   MEMORIA ESTRUCTURADA DEL PROYECTO
   Vive en <datos>/memory/<proyecto>.json, fuera de la carpeta
   del proyecto (no ensucia git y el agente no la edita a mano).
   Forge la inyecta en el prompt antes de cada turno del agente.
   ========================================================= */
const MEM_SECTIONS = ['arquitectura', 'decisiones', 'sistemas', 'bugs', 'dependencias', 'assets', 'objetivos', 'historial'];
const MEM_MAX_ITEMS = 25;
const MEM_MAX_CHARS = 300;
function memFile(project) { return path.join(MEMORY_DIR, slugProject(project) + '.json'); }
function memLoad(project) {
  try {
    const j = JSON.parse(fs.readFileSync(memFile(project), 'utf8'));
    const out = {};
    for (const s of MEM_SECTIONS) out[s] = Array.isArray(j[s]) ? j[s].filter((x) => typeof x === 'string') : [];
    return out;
  } catch (_) {
    const out = {};
    for (const s of MEM_SECTIONS) out[s] = [];
    return out;
  }
}
function memSave(project, mem) {
  const f = memFile(project);
  fs.writeFileSync(f + '.tmp', JSON.stringify(mem, null, 1), 'utf8');
  fs.renameSync(f + '.tmp', f);
}
function memFormat(project) {
  const mem = memLoad(project);
  const parts = [];
  for (const s of MEM_SECTIONS) {
    if (mem[s].length) parts.push(s + ':\n' + mem[s].map((t, i) => '  ' + (i + 1) + '. ' + t).join('\n'));
  }
  const text = parts.join('\n');
  return text.length > 6000 ? text.slice(0, 6000) + '\n[...memoria recortada: resumí o borrá entradas viejas]' : text;
}
registerTool({
  name: 'project_memory',
  label: 'Guardando en la memoria ({section})',
  description: 'Memoria estructurada y persistente del proyecto (se te muestra al inicio de cada turno). Secciones: arquitectura, decisiones, sistemas (lo ya implementado), bugs (conocidos), dependencias, assets, objetivos, historial. op="add" agrega una línea corta (máx. 300 caracteres); op="remove" borra la línea número "index" (1 = primera, según se te muestra); op="clear" vacía la sección. Guardá hechos duraderos, no charla.',
  input_schema: { type: 'object', properties: {
    op: { type: 'string', enum: ['add', 'remove', 'clear'] },
    section: { type: 'string', enum: MEM_SECTIONS },
    text: { type: 'string', description: 'Para add: la línea a guardar.' },
    index: { type: 'number', description: 'Para remove: número de línea (desde 1).' },
  }, required: ['op', 'section'] },
  permission: 'auto',
  run(input, { project }) {
    if (!MEM_SECTIONS.includes(input.section)) throw new Error('Sección inválida. Usá: ' + MEM_SECTIONS.join(', ') + '.');
    const mem = memLoad(project);
    const list = mem[input.section];
    if (input.op === 'add') {
      const t = need(input, 'text').trim().replace(/\s+/g, ' ').slice(0, MEM_MAX_CHARS);
      if (list.includes(t)) return 'Ya estaba guardado en "' + input.section + '".';
      if (list.length >= MEM_MAX_ITEMS) throw new Error('"' + input.section + '" ya tiene ' + MEM_MAX_ITEMS + ' entradas: borrá o resumí alguna antes de agregar.');
      list.push(t);
    } else if (input.op === 'remove') {
      const i = Math.floor(Number(input.index)) - 1;
      if (!(i >= 0 && i < list.length)) throw new Error('No existe la línea ' + input.index + ' en "' + input.section + '" (hay ' + list.length + ').');
      list.splice(i, 1);
    } else if (input.op === 'clear') {
      list.length = 0;
    } else {
      throw new Error('op debe ser add, remove o clear.');
    }
    memSave(project, mem);
    return '"' + input.section + '" ahora tiene ' + list.length + ' entrada(s).';
  },
});

async function callTool(body) {
  const def = TOOLS.get(body && body.name);
  if (!def) return { status: 404, body: { ok: false, text: 'Herramienta desconocida: "' + (body && body.name) + '".' } };
  const input = body.input && typeof body.input === 'object' && !Array.isArray(body.input) ? body.input : {};
  const base = projectDir(body.project);
  let perm = typeof def.permission === 'function' ? def.permission(input) : def.permission;
  if (typeof perm === 'string') perm = { level: perm };
  if (perm.level === 'blocked') return { status: 200, body: { ok: false, text: 'Bloqueado por seguridad: ' + perm.reason } };
  if (perm.level === 'confirm' && !body.confirmed) {
    let summary = def.name;
    try { summary = def.summary ? def.summary(input) : def.name; } catch (_) { /* usa el nombre */ }
    return { status: 200, body: { ok: false, needs_confirmation: true, summary, reason: perm.reason || '' } };
  }
  try {
    const r = await def.run(input, { base, project: body.project });
    const res = typeof r === 'string' ? { ok: true, text: r } : r;
    return { status: 200, body: { ok: !!res.ok, text: String(res.text) } };
  } catch (e) {
    return { status: 200, body: { ok: false, text: cleanMsg(e, base) } };
  }
}
function readBody(req, limit) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) { reject(new Error('Cuerpo demasiado grande.')); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const server = http.createServer((req, res) => {
  if (!hostAllowed(req)) {
    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
    return res.end('Host no permitido.');
  }
  const url = new URL(req.url, `http://${HOST}:${PORT}`);

  if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/forge.html')) {
    return serveHtml(res);
  }

  // PWA: manifiesto, icono y service worker mínimo (sin caché: la página lleva un token distinto en cada arranque)
  if (req.method === 'GET' && url.pathname === '/manifest.webmanifest') {
    res.writeHead(200, { 'Content-Type': 'application/manifest+json; charset=utf-8' });
    return res.end(JSON.stringify({ name: 'Forge', short_name: 'Forge', start_url: '/', scope: '/', display: 'standalone', background_color: '#0e1116', theme_color: '#e4491c', icons: [{ src: '/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any maskable' }] }));
  }
  if (req.method === 'GET' && url.pathname === '/icon.svg') {
    res.writeHead(200, { 'Content-Type': 'image/svg+xml' });
    return res.end('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ff8a3d"/><stop offset=".6" stop-color="#e4491c"/><stop offset="1" stop-color="#b8320f"/></linearGradient></defs><rect width="512" height="512" fill="url(#g)"/><path fill="#fff" transform="translate(96 96) scale(13.3)" d="M12 2.5c.8 3.6 5 5.6 5 10.2a5 5 0 0 1-10 0c0-2 .9-3.3 2-4.2.1 2 1 3 2 3.2C11 8.8 10.5 6 12 2.5z"/></svg>');
  }
  if (req.method === 'GET' && url.pathname === '/sw.js') {
    res.writeHead(200, { 'Content-Type': 'text/javascript; charset=utf-8', 'Cache-Control': 'no-store' });
    return res.end("self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',()=>{});");
  }

  if (url.pathname.startsWith('/api/')) {
    if (!tokenOk(req)) return sendJson(res, 401, { ok: false, error: 'Token inválido. Recargá Forge desde el servidor.' });

    if (req.method === 'GET' && url.pathname === '/api/health') {
      return sendJson(res, 200, {
        ok: true,
        name: 'forge-engine',
        version: VERSION,
        node: process.version,
        platform: process.platform,
        uptime: Math.round((Date.now() - STARTED) / 1000),
        projectsDir: PROJECTS_DIR,
        tools: TOOLS.size,
      });
    }
    if (req.method === 'GET' && url.pathname === '/api/tools') {
      return sendJson(res, 200, {
        ok: true,
        tools: [...TOOLS.values()].map((t) => ({ name: t.name, label: t.label || t.name, description: t.description, input_schema: t.input_schema })),
      });
    }
    if (req.method === 'GET' && url.pathname === '/api/memory') {
      return sendJson(res, 200, { ok: true, text: memFormat(url.searchParams.get('project')) });
    }
    if (req.method === 'POST' && url.pathname === '/api/tools/call') {
      return readBody(req, 8 * 1024 * 1024)
        .then((raw) => {
          let body;
          try { body = JSON.parse(raw); } catch (_) { return sendJson(res, 400, { ok: false, text: 'JSON inválido.' }); }
          return callTool(body).then((r) => sendJson(res, r.status, r.body));
        })
        .catch((e) => sendJson(res, 400, { ok: false, text: String((e && e.message) || e) }));
    }
    // Chats en disco: <datos>/chats/<id>.json (+ <id>.meta con la fecha, para listar sin leer todo)
    if (url.pathname === '/api/chats' && req.method === 'GET') {
      const out = [];
      for (const f of fs.readdirSync(CHATS_DIR)) {
        if (!f.endsWith('.meta')) continue;
        try { const m = JSON.parse(fs.readFileSync(path.join(CHATS_DIR, f), 'utf8')); out.push({ id: f.slice(0, -5), updatedAt: Number(m.updatedAt) || 0 }); } catch (_) { /* meta dañado: se ignora */ }
      }
      return sendJson(res, 200, { ok: true, chats: out });
    }
    const cm = url.pathname.match(/^\/api\/chats\/([A-Za-z0-9]{1,40})$/);
    if (cm) {
      const f = path.join(CHATS_DIR, cm[1] + '.json'), mf = path.join(CHATS_DIR, cm[1] + '.meta');
      if (req.method === 'GET') {
        if (!fs.existsSync(f)) return sendJson(res, 404, { ok: false, error: 'No existe.' });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
        return res.end(fs.readFileSync(f));
      }
      if (req.method === 'DELETE') {
        for (const x of [f, mf]) { try { fs.unlinkSync(x); } catch (_) { /* ya no estaba */ } }
        return sendJson(res, 200, { ok: true });
      }
      if (req.method === 'PUT') {
        return readBody(req, 128 * 1024 * 1024)
          .then((raw) => {
            const c = JSON.parse(raw);
            if (!c || c.id !== cm[1]) return sendJson(res, 400, { ok: false, error: 'Id no coincide.' });
            fs.writeFileSync(f + '.tmp', raw, 'utf8'); fs.renameSync(f + '.tmp', f);
            fs.writeFileSync(mf, JSON.stringify({ updatedAt: c.updatedAt || Date.now() }), 'utf8');
            return sendJson(res, 200, { ok: true });
          })
          .catch((e) => sendJson(res, 400, { ok: false, error: String((e && e.message) || e) }));
      }
    }
    return sendJson(res, 404, { ok: false, error: 'Ruta no encontrada.' });
  }

  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('No encontrado.');
});

server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`El puerto ${PORT} ya está en uso. ¿Ya hay un Forge Engine abierto? Usá otro puerto: FORGE_PORT=8788 node forge-server.js`);
  } else {
    console.error('Error del servidor:', err.message);
  }
  process.exit(1);
});

server.listen(PORT, HOST, () => {
  console.log(`Forge Engine ${VERSION} listo.`);
  console.log(`Abrí en tu navegador:  http://${HOST}:${PORT}`);
  console.log(`Datos en: ${HOME}`);
  console.log('Para cerrarlo: Ctrl+C');
  openBrowser(`http://${HOST}:${PORT}`);
});

// Intenta abrir el navegador solo (Termux). Si no puede, no pasa nada: la URL ya está impresa.
function openBrowser(url) {
  if (process.env.FORGE_NO_OPEN) return;
  try {
    const p = spawn('termux-open-url', [url], { stdio: 'ignore', detached: true });
    p.on('error', () => {});
    p.unref();
  } catch (_) { /* sin apertura automática */ }
}